public abstract class AbstractScriptTraceRmiLaunchOffer : AbstractTraceRmiLaunchOffer {

	protected File script;
	protected string configName;
	protected ScriptAttributes attrs;

	public AbstractScriptTraceRmiLaunchOffer(TraceRmiLauncherServicePlugin plugin, Program program,
			File script, string configName, ScriptAttributes attrs) : base(plugin, program)
    {
		this.script = script;
		this.configName = configName;
		this.attrs = attrs;
	}

	/* @Override */
	public string getConfigName() {
		return configName;
	}

