	public Icon getIcon() {
		return attrs.icon();
	}

	/* @Override */
	public HelpLocation getHelpLocation() {
		return attrs.helpLocation();
	}

	/* @Override */
	public Map<string, LaunchParameter<object>> getParameters() {
